24: export class GolfBallPhysics {
25:   readonly body: RAPIER.RigidBody;
26:   readonly collider: RAPIER.Collider;
27:   lastSafePosition: Vec3;
28:   private quietSeconds = 0;
29:   private readonly rollingResistance: number;
30:   private readonly airResistance: number;
31: 
32:   constructor(physics: PhysicsWorld, spawn: Vec3, options: GolfBallPhysicsOptions = {}) {
33:     const config = GAME_CONFIG.physics;
34:     const radius = options.radius ?? config.ballRadius;
35:     const mass = options.mass ?? config.ballMass;
36:     this.rollingResistance = options.rollingResistance ?? 0.32;
37:     this.airResistance = options.airResistance ?? 0.018;
38:     this.body = physics.world.createRigidBody(
39:       RAPIER.RigidBodyDesc.dynamic()
40:         .setTranslation(spawn.x, spawn.y, spawn.z)
41:         .setLinearDamping(options.linearDamping ?? 0.08)
42:         .setAngularDamping(options.angularDamping ?? 0.22)
43:         .setCcdEnabled(true),
44:     );
45:     this.collider = physics.world.createCollider(
46:       RAPIER.ColliderDesc.ball(radius)
47:         .setMass(mass)
48:         .setFriction(options.friction ?? 0.55)
49:         .setRestitution(options.restitution ?? 0.32)
50:         .setCollisionGroups(BALL_COLLISION_GROUPS),
51:       this.body,
52:     );
53:     this.lastSafePosition = { ...spawn };
54:   }
55: 
56:   get position(): Vec3 {
57:     const p = this.body.translation();
58:     return { x: p.x, y: p.y, z: p.z };
59:   }
60: 
61:   get velocity(): Vec3 {
62:     const v = this.body.linvel();
63:     return { x: v.x, y: v.y, z: v.z };
64:   }
65: 
66:   get speed(): number {
67:     return magnitude(this.velocity);
68:   }
69: 
70:   get canShoot(): boolean {
71:     return this.body.isSleeping() || this.speed <= GAME_CONFIG.physics.ballStopThreshold;
72:   }
73: 
74:   applyShot(direction: Vec3, charge: number): ShotResult {
75:     if (!this.canShoot) return { accepted: false, impulse: 0 };
76:     const normalized = normalizeHorizontal(direction);
77:     if (!normalized) return { accepted: false, impulse: 0 };
78:     const cfg = GAME_CONFIG.physics;
79:     const impulse = shotImpulseFromCharge(charge, cfg.minShotPower, cfg.maxShotPower, cfg.powerExponent);
80:     this.body.wakeUp();
81:     this.body.applyImpulse({ x: normalized.x * impulse, y: 0, z: normalized.z * impulse }, true);
82:     this.limitSpeed();
83:     this.quietSeconds = 0;
84:     return { accepted: true, impulse };
85:   }
86: 
87:   update(dt: number): void {
88:     const cfg = GAME_CONFIG.physics;
89:     const velocity = this.velocity;
90:     const speed = magnitude(velocity);
91:     if (speed > cfg.ballStopThreshold) {
92:       this.quietSeconds = 0;
93:       const horizontalSpeed = Math.hypot(velocity.x, velocity.z);
94:       if (horizontalSpeed > 1e-6) {
95:         const rolling = Math.max(0, 1 - this.rollingResistance * dt);
96:         const air = 1 / (1 + this.airResistance * speed * dt);
97:         this.body.setLinvel({ x: velocity.x * rolling * air, y: velocity.y * air, z: velocity.z * rolling * air }, true);
98:       }
99:       this.limitSpeed();
100:       return;
101:     }
102:     this.quietSeconds += dt;
103:     if (shouldSleep(speed, cfg.ballStopThreshold, this.quietSeconds, cfg.sleepDelaySeconds)) {
104:       this.body.setLinvel({ x: 0, y: 0, z: 0 }, false);
105:       this.body.setAngvel({ x: 0, y: 0, z: 0 }, false);
106:       this.body.sleep();
107:     }
108:   }
109: 
110:   markSafePosition(position: Vec3 = this.position): void {
111:     this.lastSafePosition = { ...position };
112:   }
113: 
114:   reset(position: Vec3 = this.lastSafePosition): void {
115:     this.body.setTranslation(position, false);
116:     this.body.setLinvel({ x: 0, y: 0, z: 0 }, false);
117:     this.body.setAngvel({ x: 0, y: 0, z: 0 }, false);
118:     this.body.resetForces(false);
119:     this.body.resetTorques(false);
120:     this.quietSeconds = 0;
121:     this.body.sleep();
122:   }
123: 
124:   private limitSpeed(): void {
125:     const limited = cappedVelocity(this.velocity, GAME_CONFIG.physics.maxBallSpeed);
126:     const current = this.velocity;
127:     if (limited.x !== current.x || limited.y !== current.y || limited.z !== current.z) {
128:       this.body.setLinvel(limited, true);
129:     }
130:   }
131: }
